m1
        dc.b $11,"YOU MOVE THE RUSTY TOOLS ASIDE.",$0d,"SOMETHING GLITTERS... A TINY PIECE OF"
        dc.b $0d,"STARLIGHT!",$0d,0
m2
        dc.b $11,"UNDER THE MAT YOU FIND A SCRAP OF",$0d,"PAPER.",$0d,0
m3
        dc.b $11,"YOU HAVE ALREADY DUG UP THE MOUND.",$0d,0
m4
        dc.b $11,"YOU DIG INTO THE SOFT EARTH... CLANG!",$0d,"YOU UNCOVER AN IRON HANDLE!"
        dc.b $0d,0
m5
        dc.b $11,"YOU SCRAPE AT THE EARTH WITH YOUR",$0d,"HANDS. IT IS NO USE, YOU NEED A TOOL."
        dc.b $0d,0
m6
        dc.b $11,"THE GROUND HERE IS FAR TOO HARD.",$0d,0
m7
        dc.b $11,"THE EARTH IS LOOSE. YOU COULD DIG HERE.",$0d,0
m8
        dc.b $11,"THE BUCKET IS ALREADY UP.",$0d,0
m9
        dc.b $11,"YOU FIT THE HANDLE ONTO THE WINCH AND",$0d,"TURN. WITH A CREAK THE BUCKET RISES OUT"
        dc.b $0d,"OF THE DARKNESS. INSIDE IT LIES A BRASS",$0d,"KEY!",$0d,0
m10
        dc.b $11,"THE WINCH HAS NO HANDLE. YOU CANNOT",$0d,"TURN IT.",$0d,0
m11
        dc.b $11,"THE BUCKET IS FAR TOO HEAVY TO PULL UP",$0d,"BY HAND.",$0d,0
m12
        dc.b $11,"IT HANGS FAR DOWN THE WELL, OUT OF",$0d,"REACH.",$0d,0
m13
        dc.b $11,"YOU CLIMB DOWN THE ROPE INTO THE",$0d,"WELL... THE OLD ROPE SNAPS! YOU PLUNGE"
        dc.b $0d,"INTO THE ICY WATER FAR BELOW.",$0d,0
m14
        dc.b $11,"YOU JUMP INTO THE WELL. NOT YOUR",$0d,"BRIGHTEST IDEA.",$0d,0
m15
        dc.b $11,"IT IS ALREADY UNLOCKED.",$0d,0
m16
        dc.b $11,"THE BRASS KEY TURNS WITH A LOUD CLUNK.",$0d,"THE DOOR CREAKS OPEN."
        dc.b $0d,0
m17
        dc.b $11,"YOU HAVE NOTHING TO UNLOCK IT WITH.",$0d,0
m18
        dc.b $11,"IT IS ALREADY OPEN.",$0d,0
m19
        dc.b $11,"THE DOOR IS LOCKED. THE LOCK IS SHAPED",$0d,"LIKE A RAVEN."
        dc.b $0d,0
m20
        dc.b $11,"YOU KNOCK. THE SOUND ECHOES THROUGH THE",$0d,"HOUSE, BUT NOBODY ANSWERS."
        dc.b $0d,0
m21
        dc.b $11,"YOU STEP INTO THE DARKNESS OF THE",$0d,"MANOR. BEHIND YOU THE DOOR SLAMS SHUT!"
        dc.b $0d,0
m22
        dc.b $11,"THE DOOR IS LOCKED.",$0d,0
m23
        dc.b $11,"THE MOUND IN THE GARDEN WAS DUG UP",$0d,"RECENTLY. MAYBE THE SHED HAS SOMETHING"
        dc.b $0d,"TO DIG WITH.",$0d,0
m24
        dc.b $11,"DIG IN THE GARDEN.",$0d,0
m25
        dc.b $11,"TAKE THE IRON HANDLE YOU DUG UP.",$0d,0
m26
        dc.b $11,"THE WINCH AT THE WELL HAS NO HANDLE.",$0d,"TURN THE HANDLE THERE."
        dc.b $0d,0
m27
        dc.b $11,"THE BUCKET BROUGHT UP A KEY. TAKE IT.",$0d,0
m28
        dc.b $11,"UNLOCK THE FRONT DOOR ON THE PORCH.",$0d,0
m29
        dc.b $11,"THE DOOR IS OPEN. GO NORTH INTO THE",$0d,"MANOR.",$0d,0
m30
        dc.b $11,"A HOLLOW VOICE SAYS: WRONG GAME. THIS",$0d,"ISN'T COLOSSAL CAVE."
        dc.b $0d,0
m31
        dc.b $11,"GOD MODE? NICE TRY. THIS IS A COMMODORE",$0d,"64, NOT A 486."
        dc.b $0d,0
m32
        dc.b $11,"THAT'S THE ANSWER TO LIFE, THE UNIVERSE",$0d,"AND EVERYTHING. BUT WHAT WAS THE"
        dc.b $0d,"QUESTION?",$0d,0
m33
        dc.b $11,"YOU WAVE YOUR HAND. THESE AREN'T THE",$0d,"COMMANDS YOU'RE LOOKING FOR."
        dc.b $0d,0
m34
        dc.b $11,"THERE IS NO LAMP HERE. THIS ISN'T ZORK,",$0d,"YOU KNOW. BUT WATCH OUT FOR GRUES"
        dc.b $0d,"ANYWAY.",$0d,0
m35
        dc.b $11,"TYPE COMMANDS LIKE TAKE KEY, OPEN DOOR,",$0d,"EXAMINE MAT, N S E W U D, L = LOOK,"
        dc.b $0d,"I = INVENTORY, TAKE ALL, DROP ALL,",$0d,"G = AGAIN, SCORE, MAP, SAVE, LOAD, QUIT"
        dc.b $0d,"F1 LOAD  F3 SAVE  F5 MUSIC  F7 QUIT",$0d,"THREE SAVE SLOTS: PRESS 1, 2 OR 3."
        dc.b $0d,"HINT GIVES A CLUE BUT COSTS 3 POINTS.",$0d,"FIND THE 16 HIDDEN STAR FRAGMENTS!"
        dc.b $0d,0
m36
        dc.b $11,"LIGHTNING FLASHES! FOR A MOMENT YOU SEE",$0d,"A PALE FACE AT AN UPSTAIRS WINDOW."
        dc.b $0d,0
t_intro
        dc.b $11,"A LETTER FROM YOUR UNCLE EDMUND BROUGHT",$0d,"YOU HERE: 'COME TO RAVENMOOR AT ONCE. I"
        dc.b $0d,"HAVE FOUND IT.' NOBODY HAS SEEN HIM",$0d,"SINCE. NOW, ON A STORMY NIGHT, YOU"
        dc.b $0d,"ARRIVE AT THE GATES OF HIS MANOR.",$0d,$0d,0
t_title
        dc.b $17,$0d,"PROLOGUE, PART 1: THE GROUNDS",$0d,$0d,0
t_short
        dc.b "PROLOGUE 1",0
t_quip
        dc.b $17,"THANK YOU FOR PLAYING THE WORLD OF",$0d,"STRONKIE. WE HOPE YOU ENJOYED YOUR VERY"
        dc.b $0d,"SHORT VISIT TO RAVENMOOR.",$0d,0
d1
        dc.b $1d,"YOU ARE ON A MUDDY ROAD BEFORE THE IRON",$0d,"GATES OF RAVENMOOR MANOR. THE GATES"
        dc.b $0d,"HANG OPEN. A PATH LEADS NORTH.",$0d,0
d2
        dc.b $1d,"YOU ARE IN AN OVERGROWN GARDEN. IN THE",$0d,"MIDDLE IS A MOUND OF FRESHLY DUG EARTH."
        dc.b $0d,"A SHED STANDS TO THE EAST, AN OLD WELL",$0d,"TO THE WEST. THE PORCH LIES NORTH."
        dc.b $0d,0
d3
        dc.b $1d,"YOU ARE INSIDE A DAMP GARDEN SHED.",$0d,"RUSTY TOOLS HANG ON THE WALLS AND"
        dc.b $0d,"COBWEBS FILL EVERY CORNER.",$0d,0
d4
        dc.b $1d,"YOU STAND BY AN OLD STONE WELL. A",$0d,"BUCKET HANGS FAR DOWN ON A ROPE. THE"
        dc.b $0d,"WINCH IS MISSING ITS HANDLE.",$0d,0
d5
        dc.b $1d,"YOU ARE ON THE PORCH OF THE MANOR. A",$0d,"HEAVY OAK DOOR LEADS NORTH. A WORN"
        dc.b $0d,"DOORMAT LIES AT YOUR FEET.",$0d,0
t0
        dc.b 0
t1
        dc.b $11,"THE IRON GATES ARE RUSTED AND HANG OPEN",$0d,"ON BROKEN HINGES."
        dc.b $0d,0
t2
        dc.b $11,"THE EARTH HAS BEEN DUG QUITE RECENTLY.",$0d,"SOMETHING MAY BE BURIED HERE."
        dc.b $0d,0
t3
        dc.b "A SHOVEL",0
t4
        dc.b $11,"A STURDY SHOVEL. GOOD FOR DIGGING.",$0d,0
t5
        dc.b $11,"ALL RUSTED BEYOND USE, EXCEPT FOR A",$0d,"SHOVEL.",$0d,0
t6
        dc.b "AN IRON HANDLE",0
t7
        dc.b $11,"A BENT IRON CRANK HANDLE WITH A SQUARE",$0d,"END. IT MUST FIT SOMETHING."
        dc.b $0d,0
t8
        dc.b $11,"THE WELL IS DEEP AND DARK. THE WINCH",$0d,"HAS A SQUARE HOLE WHERE A HANDLE SHOULD"
        dc.b $0d,"GO. YOU HALF EXPECT A KING WITH A",$0d,"FEATHER IN HIS CAP TO CLIMB OUT OF IT."
        dc.b $0d,0
t9
        dc.b $11,"IT HANGS TOO FAR DOWN TO REACH.",$0d,0
t10
        dc.b "A BRASS KEY",0
t11
        dc.b $11,"A LARGE BRASS KEY. ITS BOW IS SHAPED",$0d,"LIKE A RAVEN.",$0d
        dc.b 0
t12
        dc.b $11,"A HEAVY OAK DOOR WITH A BRASS LOCK",$0d,"SHAPED LIKE A RAVEN."
        dc.b $0d,0
t13
        dc.b $11,"A WORN DOORMAT. IT SAYS WELCOME, BUT IT",$0d,"DOES NOT MEAN IT."
        dc.b $0d,0
t14
        dc.b "A SCRAP OF PAPER",0
t15
        dc.b $11,"IT READS: 'I BURIED THE WINCH HANDLE SO",$0d,"THEY CANNOT RAISE THE KEY. - E.'"
        dc.b $0d,0
